package dev.joaomendonca.agendapro.appointment.api;import dev.joaomendonca.agendapro.appointment.application.AppointmentService;import jakarta.validation.Valid;import org.springframework.format.annotation.DateTimeFormat;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.net.URI;import java.time.LocalDate;import java.util.*;
@RestController @RequestMapping("/api/v1/appointments") @PreAuthorize("hasAnyRole('OWNER','ADMIN')") public class AppointmentController{private final AppointmentService service;public AppointmentController(AppointmentService service){this.service=service;}@PostMapping public ResponseEntity<AppointmentResponse> create(@Valid @RequestBody AppointmentRequest r){var a=service.create(r);return ResponseEntity.created(URI.create("/api/v1/appointments/"+a.id())).body(a);}@GetMapping public List<AppointmentResponse> list(@RequestParam(required=false) @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate from,@RequestParam(required=false) @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate to){return service.list(from,to);}@GetMapping("/{id}") public AppointmentResponse get(@PathVariable UUID id){return service.get(id);}@PutMapping("/{id}") public AppointmentResponse update(@PathVariable UUID id,@Valid @RequestBody AppointmentRequest r){return service.update(id,r);}@PatchMapping("/{id}/status") public AppointmentResponse status(@PathVariable UUID id,@Valid @RequestBody AppointmentStatusRequest r){return service.status(id,r);}}
